-- Read-only prerequisite check. Requires visible metadata in both databases.
:ON ERROR EXIT
SET NOCOUNT ON;
IF DB_ID(N'baocaosct.khanhhoa.gov.vn.cate') IS NULL OR DB_ID(N'baocaosct.khanhhoa.gov.vn') IS NULL
 THROW 50120,'Both existing application databases are required; this is not an empty-database bootstrap.',1;
USE [baocaosct.khanhhoa.gov.vn];
IF EXISTS(SELECT 1 FROM sys.databases WHERE name IN(N'baocaosct.khanhhoa.gov.vn.cate',N'baocaosct.khanhhoa.gov.vn') AND compatibility_level<110)
 THROW 50121,'Compatibility level 110 or higher is required.',1;
SELECT o.name BaseProcedure,d.referenced_database_name ExistingDatabase,d.referenced_schema_name ExistingSchema,d.referenced_entity_name ExistingObject FROM [baocaosct.khanhhoa.gov.vn].sys.sql_expression_dependencies d JOIN [baocaosct.khanhhoa.gov.vn].sys.objects o ON o.object_id=d.referencing_id WHERE o.name IN('p_Report_DataImports_ImportDatas','p_Report_DataImports_Delete','p_Report_DataImports_CheckDataImport') AND d.referenced_database_name IS NOT NULL ORDER BY o.name,d.referenced_database_name,d.referenced_entity_name;
