 INSERT @Required VALUES(N'baocaosct.khanhhoa.gov.vn.cate',N'Report_UserBusinessIndustryPermissions',N'UserId'),(N'baocaosct.khanhhoa.gov.vn.cate',N'Report_UserBusinessIndustryPermissions',N'IndustryId'),(N'baocaosct.khanhhoa.gov.vn.cate',N'Report_UserBusinessIndustryPermissions',N'SavedBy'),(N'baocaosct.khanhhoa.gov.vn.cate',N'Report_UserBusinessIndustryPermissions',N'SavedOn');
SELECT DatabaseName,ObjectName,ColumnName,'MISSING OR METADATA NOT VISIBLE' Status FROM @Required
WHERE OBJECT_ID(QUOTENAME(DatabaseName)+'.dbo.'+QUOTENAME(ObjectName)) IS NULL
 OR (ColumnName IS NOT NULL AND COL_LENGTH(QUOTENAME(DatabaseName)+'.dbo.'+QUOTENAME(ObjectName),ColumnName) IS NULL);
IF EXISTS(SELECT 1 FROM @Required WHERE OBJECT_ID(QUOTENAME(DatabaseName)+'.dbo.'+QUOTENAME(ObjectName)) IS NULL
 OR (ColumnName IS NOT NULL AND COL_LENGTH(QUOTENAME(DatabaseName)+'.dbo.'+QUOTENAME(ObjectName),ColumnName) IS NULL))
 THROW 50123,'Required deployment dependencies are missing or inaccessible. Inspect the preceding object/column rows before deploying.',1;
IF NOT EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn.cate].sys.columns c JOIN [baocaosct.khanhhoa.gov.vn.cate].sys.tables t ON t.object_id=c.object_id
 JOIN [baocaosct.khanhhoa.gov.vn.cate].sys.schemas s ON s.schema_id=t.schema_id
 WHERE s.name='dbo' AND t.name='Sys_Messages' AND c.name='Message' AND c.system_type_id IN(99,231,239))
 THROW 50123,'Sys_Messages.Message must be a Unicode type (ntext/nvarchar/nchar).',1;
SELECT 'PASS' PreflightStatus,'Existing dependency objects and required index/label columns found; stage execution still required.' Detail;
-- Informational only: these exports are not created or called by this release.
SELECT plugin.ObjectName,CASE WHEN OBJECT_ID(N'[baocaosct.khanhhoa.gov.vn].dbo.'+plugin.ObjectName,N'P') IS NULL
 THEN 'NOT INSTALLED OR NOT VISIBLE (optional export)' ELSE 'INSTALLED' END AS OptionalExportStatus
FROM (VALUES(N'usp_Report_KTXH_TheoEnterprise'),(N'usp_Report_KTXH_Tong'),
 (N'usp_Report_KTXH_Type2_TheoEnterprise'),(N'usp_Report_KTXH_Type2_Tong'),
 (N'usp_Report_HoatDongXuatKhau_TheoEnterprise')) plugin(ObjectName);
IF OBJECT_ID(N'[baocaosct.khanhhoa.gov.vn.cate].dbo.Report_RoleMappings','U') IS NOT NULL
 AND (COL_LENGTH(N'[baocaosct.khanhhoa.gov.vn.cate].dbo.Report_RoleMappings',N'ScopeMode') IS NULL
 OR COL_LENGTH(N'[baocaosct.khanhhoa.gov.vn.cate].dbo.Report_RoleMappings',N'IsProvince') IS NOT NULL)
 THROW 50124,'Existing release mapping schema is incompatible; review before deployment.',1;
DECLARE @RoleMap TABLE(SemanticKey varchar(80),RoleId int,ScopeMode varchar(10),IsIndustryEditorTarget bit);
INSERT @RoleMap VALUES ('SystemAdministrator',1,'all',1),
('ReportingRole2',2,'industry',1),
('ReportingRole3',3,'industry',1),
('ReportingRole4',4,'industry',1),
('Enterprise',5,'enterprise',0),
('IndustryAdministrator',6,'industry',1);
IF EXISTS(SELECT 1 FROM @RoleMap m LEFT JOIN [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_Roles r ON r.RoleId=m.RoleId WHERE r.RoleId IS NULL OR r.IsDeleted<>0)
 THROW 50124,'Configured role is missing, deleted or inaccessible.',1;
IF NOT EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_Functions WHERE Area='Report' AND Name='Dashboard' AND IsDeleted=0)
 OR NOT EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_Functions WHERE Area='Report' AND Name='Import' AND IsDeleted=0)
 OR NOT EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_Functions WHERE Area='Cate' AND Name='Enterprise' AND IsDeleted=0)
 THROW 50124,'Required reporting/registry functions are missing or deleted.',1;
-- Province mapping is eligibility only: existing function permissions still decide actual access.
IF EXISTS(SELECT 1 FROM @RoleMap m JOIN [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_Permissions p ON p.RoleId=m.RoleId
 JOIN [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_Functions f ON f.FunctionId=p.FunctionId AND f.IsDeleted=0
 WHERE m.ScopeMode='enterprise' AND f.Area='Sys' AND f.Name='User' AND p.Action IN('Add','Edit','Delete'))
 THROW 50124,'Enterprise role has forbidden user-management permissions.',1;
IF NOT EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_Permissions p JOIN [baocaosct.khanhhoa.gov.vn.cate].dbo.Sys_Functions f ON f.FunctionId=p.FunctionId AND f.IsDeleted=0
 JOIN @RoleMap m ON m.RoleId=p.RoleId WHERE m.SemanticKey='SystemAdministrator' AND f.Area='Sys' AND f.Name='User' AND p.Action='Edit')
 THROW 50124,'System administrator requires Sys/User/Edit.',1;
IF NOT EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn].sys.table_types t JOIN [baocaosct.khanhhoa.gov.vn].sys.schemas s ON s.schema_id=t.schema_id WHERE s.name='dbo' AND t.name='DataReport')
 OR NOT EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn].sys.table_types t JOIN [baocaosct.khanhhoa.gov.vn].sys.schemas s ON s.schema_id=t.schema_id WHERE s.name='dbo' AND t.name='DataReportWithIndexLevel')
