aocaosct.khanhhoa.gov.vn].sys.index_columns k JOIN [baocaosct.khanhhoa.gov.vn].sys.columns c ON c.object_id=k.object_id AND c.column_id=k.column_id WHERE k.object_id=i.object_id AND k.index_id=i.index_id AND c.name=N'ComparedSamePeriodLastYear')) AND (i.type=1 OR EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn].sys.index_columns k JOIN [baocaosct.khanhhoa.gov.vn].sys.columns c ON c.object_id=k.object_id AND c.column_id=k.column_id WHERE k.object_id=i.object_id AND k.index_id=i.index_id AND c.name=N'CreatedDate')) AND (i.type=1 OR EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn].sys.index_columns k JOIN [baocaosct.khanhhoa.gov.vn].sys.columns c ON c.object_id=k.object_id AND c.column_id=k.column_id WHERE k.object_id=i.object_id AND k.index_id=i.index_id AND c.name=N'IsDeleted')) AND (i.type=1 OR EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn].sys.index_columns k JOIN [baocaosct.khanhhoa.gov.vn].sys.columns c ON c.object_id=k.object_id AND c.column_id=k.column_id WHERE k.object_id=i.object_id AND k.index_id=i.index_id AND c.name=N'IsLate')) AND (i.type=1 OR EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn].sys.index_columns k JOIN [baocaosct.khanhhoa.gov.vn].sys.columns c ON c.object_id=k.object_id AND c.column_id=k.column_id WHERE k.object_id=i.object_id AND k.index_id=i.index_id AND c.name=N'LastModifiedDate')) AND (i.type=1 OR EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn].sys.index_columns k JOIN [baocaosct.khanhhoa.gov.vn].sys.columns c ON c.object_id=k.object_id AND c.column_id=k.column_id WHERE k.object_id=i.object_id AND k.index_id=i.index_id AND c.name=N'PerformInPeriod')) AND (i.type=1 OR EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn].sys.index_columns k JOIN [baocaosct.khanhhoa.gov.vn].sys.columns c ON c.object_id=k.object_id AND c.column_id=k.column_id WHERE k.object_id=i.object_id AND k.index_id=i.index_id AND c.name=N'PerformPreviousPeriod')) AND (i.type=1 OR EXISTS(SELECT 1 FROM [baocaosct.khanhhoa.gov.vn].sys.index_columns k JOIN [baocaosct.khanhho